	@Override
	public void setupAnim(State state) {
		super.setupAnim(state);
		head.yRot += state.yRot * 0.017453292F * 1.0F;
		head.xRot += state.xRot * 0.017453292F * 1.0F;
		arm_l.zRot += Mth.sin(state.ageInTicks * 0.09F + 0.0F) * (0.03F + 0.0F * state.walkAnimationSpeed);
		leg_l.xRot += Mth.cos(state.walkAnimationPos * 0.6662F + 3.141592653589793F) * 0.8800000000000001F * state.walkAnimationSpeed;
		arm_r.zRot += Mth.sin(state.ageInTicks * 0.09F + 3.141592653589793F) * (0.03F + 0.0F * state.walkAnimationSpeed);
		leg_r.xRot += Mth.cos(state.walkAnimationPos * 0.6662F + 0.0F) * 0.8800000000000001F * state.walkAnimationSpeed;
		cape.xRot += Mth.sin(state.ageInTicks * 0.08F + 0.0F) * (0.06F + 0.25F * state.walkAnimationSpeed);
		rag_f.xRot += Mth.sin(state.ageInTicks * 0.1F + 0.0F) * (0.05F + 0.2F * state.walkAnimationSpeed);
	}
